import SwiftUI
import Observation

struct StudySession: Identifiable {
    let id = UUID()
    let minutes: Int
}

@Observable
final class SessionStore {
    var sessions: [StudySession] = []

    func record(minutes: Int) {
        sessions.append(StudySession(minutes: minutes))
    }

    func averageMinutes() -> Int {
        guard !sessions.isEmpty else { return 0 }
        return sessions.map(\.minutes).reduce(0, +) / sessions.count
    }
}

struct StudyTimerView: View {
    @State private var store = SessionStore()
    @State private var secondsLeft = 25 * 60

    var body: some View {
        VStack(spacing: 16) {
            Text("\(secondsLeft / 60):\(String(format: "%02d", secondsLeft % 60))")
                .font(.largeTitle.monospacedDigit())
            Button("Start") { startCountdown() }
            SessionSummaryView()
        }
        .environment(store)
    }

    private func startCountdown() {
        DispatchQueue.global().async {
            while secondsLeft > 0 {
                Thread.sleep(forTimeInterval: 1)
                secondsLeft -= 1
            }
            store.record(minutes: 25)
        }
    }
}

struct SessionSummaryView: View {
    @State private var store = SessionStore()

    var body: some View {
        Text("Sessions: \(store.sessions.count), average \(store.averageMinutes()) min")
    }
}

