@Observable
final class EntryEditorViewModel {
    var title = ""
    var body = ""
    var date = Date()
    var statusText = ""
    private let directory: URL

    init(directory: URL) {
        self.directory = directory
    }

    func save() {
        if !title.isEmpty {
            if !body.isEmpty {
                let formatter = DateFormatter()
                formatter.dateFormat = "yyyy-MM-dd"
                let slug = title.lowercased().replacingOccurrences(of: " ", with: "-")
                let name = formatter.string(from: date) + "-" + slug + ".md"
                let url = directory.appending(path: name)
                let text = "# \(title)\n\n\(body)\n"
                do {
                    try text.write(to: url, atomically: true, encoding: .utf8)
                    statusText = "Saved \(name)"
                } catch {
                    statusText = "Could not save the entry."
                }
            } else {
                statusText = "Write something first."
            }
        } else {
            statusText = "Add a title first."
        }
    }
}

