package io.nimbus.auth

import java.time.Clock
import java.time.Duration
import java.time.Instant

class TokenCache(
    private val client: AuthClient,
    private val clock: Clock = Clock.systemUTC(),
    private val ttl: Duration = Duration.ofMinutes(5),
) {
    private data class Entry(val token: String, val fetchedAt: Instant)

    private val entries = HashMap<String, Entry>()

    fun tokenFor(user: String): String? {
        val cached = entries[user]
        if (cached != null && Duration.between(cached.fetchedAt, clock.instant()) < ttl) {
            return cached.token
        }
        return try {
            val fresh = client.fetchToken(user)
            entries[user] = Entry(fresh, clock.instant())
            fresh
        } catch (e: AuthServiceException) {
            null
        }
    }
}

