package dev.drift.gateway

import java.sql.SQLException
import java.sql.Timestamp
import javax.sql.DataSource
import org.slf4j.LoggerFactory

class BatchWriter(private val dataSource: DataSource) {
    private val log = LoggerFactory.getLogger(BatchWriter::class.java)

    companion object {
        const val BATCH_SIZE = 500
    }

    fun write(readings: List<Reading>) {
        readings.chunked(BATCH_SIZE).forEach { batch ->
            try {
                dataSource.connection.use { conn ->
                    conn.prepareStatement(INSERT).use { stmt ->
                        batch.forEach { r ->
                            stmt.setString(1, r.sensorId)
                            stmt.setDouble(2, r.value)
                            stmt.setTimestamp(3, Timestamp.from(r.takenAt))
                            stmt.addBatch()
                        }
                        stmt.executeBatch()
                    }
                }
            } catch (e: SQLException) {
                // best effort
            }
        }
        log.debug("Wrote {} readings", readings.size)
    }
}

