def normalize_rows(rows: list[dict]) -> list[dict]:
    result = []
    for row in rows:
        currency = row.get("currency", "").upper()
        if currency not in KNOWN_CURRENCIES:
            print(f"skipping row {row.get('id')}: unknown currency {currency!r}")
