export async function processThumbnails(keys: string[], sizes: number[]) {
  const results: string[] = [];
  for (const key of keys) {
    if (key.endsWith(".png") || key.endsWith(".jpg")) {
      const data = await download(key);
      if (data) {
        if (data.length < 20_000_000) {
          for (const size of sizes) {
            const out = await sharp(data).resize(size).toBuffer();
            if (out.length > 0) {
              await upload(`${key}.${size}.webp`, out);
              results.push(`${key}.${size}.webp`);
            }
          }
        }
      }
    }
  }
  return results;
}

