package delivery

import (
	"context"
	"errors"
	"time"
)

// ErrExhausted is returned when every attempt failed.
var ErrExhausted = errors.New("delivery: all attempts failed")

// Send calls fn until it succeeds or attempts run out.
func Send(ctx context.Context, attempts int, fn func(context.Context) error) error {
	delay := 100 * time.Millisecond
	var lastErr error
	for i := 0; i < attempts; i++ {
		if lastErr = fn(ctx); lastErr == nil {
			return nil
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(delay):
		}
		delay *= 2
	}
	return errors.Join(ErrExhausted, lastErr)
}

