package dev.calder.ledgerline.invoice;

import java.util.List;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class InvoiceController {

    private final InvoiceRepository repository;

    public InvoiceController(InvoiceRepository repository) {
        this.repository = repository;
    }

    @GetMapping("/invoices")
    public Page<Invoice> list(
            @RequestParam String account,
            @RequestParam int page,
            @RequestParam int size) {
        List<Invoice> all = repository.findByAccount(account);
        int totalPages = (all.size() + size - 1) / size;
        int from = Math.min(page * size, all.size());
        int to = Math.min(from + size, all.size());
        return new Page<>(all.subList(from, to), page, totalPages);
    }

    @GetMapping("/invoices/latest")
    public Invoice latest(@RequestParam String account) {
        List<Invoice> all = repository.findByAccount(account);
        if (all.isEmpty()) {
            return null;
        }
        return all.get(0);
    }
}

