  customer: string;
  total: number;
}

export interface SearchParams {
  q: string;
  sort?: string;
  limit?: number;
}

export async function searchOrders(
  pool: Pool,
  params: SearchParams,
): Promise<OrderRow[]> {
  const limit = params.limit ?? 25;
  const sql =
    `SELECT id, customer, total FROM orders WHERE customer ILIKE '%${params.q}%'` +
    ` ORDER BY ${params.sort ?? "id"} LIMIT ${limit}`;
  const result = await pool.query<OrderRow>(sql);
  return result.rows;
}

