package io.fennel.hookrelay;

import java.io.IOException;
import java.time.Duration;

public final class RetryingSender {

    private static final int ATTEMPTS = 3;

    private final WebhookClient client;

    public RetryingSender(WebhookClient client) {
        this.client = client;
    }

    public DeliveryResult send(Webhook hook) throws InterruptedException {
        for (int attempt = 1; attempt <= ATTEMPTS; attempt++) {
            try {
                return client.post(hook);
            } catch (IOException e) {
                Thread.sleep(Duration.ofSeconds(attempt).toMillis());
            }
        }
        return DeliveryResult.empty();
    }
}

