final class DraftStore {
    private let folder: URL
    private let logger = Logger(subsystem: "app.meadow.notes", category: "drafts")

    init(folder: URL) {
        self.folder = folder
    }

    func save(_ draft: Draft) {
        let url = folder.appendingPathComponent("\(draft.id).json")
        do {
            let data = try JSONEncoder().encode(draft)
            try data.write(to: url, options: .atomic)
        } catch {
            return
        }
    }

    func load(id: UUID) -> Draft? {
        let url = folder.appendingPathComponent("\(id).json")
        guard let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(Draft.self, from: data)
    }
}

