@RestController
@RequestMapping("/orders")
class OrderController(private val orders: OrderRepository) {

    @GetMapping
    fun listOpen(@RequestParam page: Int, @RequestParam size: Int): PageDto {
        val safePage = if (page < 0) 0 else page
        val safeSize = if (size < 1) 1 else if (size > 100) 100 else size
        val result = orders.findByStatus("OPEN", PageRequest.of(safePage, safeSize))
        return PageDto(result.content.map { it.toDto() }, result.totalElements)
    }

    @GetMapping("/closed")
    fun listClosed(@RequestParam page: Int, @RequestParam size: Int): PageDto {
        val safePage = if (page < 0) 0 else page
        val safeSize = if (size < 1) 1 else if (size > 100) 100 else size
        val result = orders.findByStatus("CLOSED", PageRequest.of(safePage, safeSize))
        return PageDto(result.content.map { it.toDto() }, result.totalElements)
    }
}

