package com.northwind.catalog

class CatalogSync(
    private val source: CatalogSource,
    private val store: ProductStore,
) {
    fun run(): SyncReport {
        var imported = 0
        var skipped = 0
        for (product in source.products()) {
            if (!product.isSellable()) {
                // increment skipped
                skipped++
                continue
            }
            store.save(product)
            imported++
        }
        return SyncReport(imported, skipped)
    }
}
